1	#!/usr/bin/env node
2	/**
3	 * 首页批量保存结果处理的页面层面回归保障。
4	 *
5	 * 启动真实 app.py 服务（与 smoke_test.py 同一后端，不模拟、不改动接口公开行为），
6	 * 用 Puppeteer 驱动系统 Chrome 打开首页，通过请求拦截分别「破坏」保存成功之后
7	 * 的那次客户列表读取，逐项验证：
8	 *
9	 * 1. 保存已确认成功、但随后客户列表读取失败：
10	 *      - 连接失败 / HTTP 非成功状态 / 响应无法解析 / 响应缺少 clients 数组
11	 *    页面仍明确显示「已成功处理 N 名客户」；成功数量以保存回复 updated_count
12	 *    为准，不按刷新后出现的记录数重算；同时提示列表暂未更新、当前资料可能仍是
13	 *    保存前内容、稍后刷新即可查看、无需再次保存；
14	 * 2. 保存确认成功后，无论列表是否读到：勾选清除、已选归零，来源/地区/行业/重要
15	 *    日期恢复「保持原值」，输入清空并回到不可填写状态；
16	 * 3. 列表读取失败时旧表格内容（编号、名称、各字段）保留，不清表、不显示
17	 *    「还没有客户记录」；结束保存等待、按钮恢复且无勾选时不可提交；不重发修改；
18	 * 4. 随后刷新/重新打开页面读取成功：显示真实资料、撤下读取失败提示；
19	 *    真实空列表正常显示空列表提示，不被当成读取失败；
20	 * 5. 保存成功且列表读取成功：显示处理数量、更新相关列、完成同样的勾选与编辑清理；
21	 * 6. 保存接口明确拒绝（HTTP 400 具体原因）：保留勾选、字段操作与已填内容供修正，
22	 *    不套用保存成功后的清理与提示。
23	 */
24	import {spawn} from "node:child_process";
25	import {dirname, join} from "node:path";
26	import {fileURLToPath} from "node:url";
27	import {mkdtempSync, rmSync} from "node:fs";
28	import {tmpdir} from "node:os";
29	import puppeteer from "puppeteer";
30	
31	const HERE = dirname(fileURLToPath(import.meta.url));
32	const APP = join(HERE, "app.py");
33	const TMP = mkdtempSync(join(tmpdir(), "clientbook-page-"));
34	const FAILURES = [];
35	let checkCount = 0;
36	
37	function check(label, cond, detail = "") {
38	  checkCount += 1;
39	  if (cond) {
40	    console.log("PASS", label);
41	  } else {
42	    FAILURES.push({label, detail: typeof detail === "string" ? detail : JSON.stringify(detail)});
43	    console.log("FAIL", label, typeof detail === "string" ? detail : JSON.stringify(detail));
44	  }
45	}
46	
47	// ---------------------------------------------------------------------------
48	// 真实 app.py 进程
49	// ---------------------------------------------------------------------------
50	function startApp(label) {
51	  const proc = spawn("python3", [
52	    APP, "serve", "--host", "127.0.0.1", "--port", "0",
53	    "--data-dir", join(TMP, label),
54	  ], {cwd: HERE, stdio: ["ignore", "pipe", "pipe"]});
55	  const port = new Promise((resolve, reject) => {
56	    let buf = "";
57	    const onData = d => {
58	      buf += d.toString();
59	      const m = buf.match(/http:\/\/127\.0\.0\.1:(\d+)/);
60	      if (m) {
61	        proc.stdout.off("data", onData);
62	        resolve(Number(m[1]));
63	      }
64	    };
65	    proc.stdout.on("data", onData);
66	    proc.on("exit", code => reject(new Error(`app.py 意外退出（${code}）：${buf}`)));
67	  });
68	  return {proc, port};
69	}
70	
71	async function waitReady(base, deadlineMs = 8000) {
72	  const deadline = Date.now() + deadlineMs;
73	  while (Date.now() < deadline) {
74	    try {
75	      const res = await fetch(base + "/health");
76	      if (res.status === 200) return;
77	    } catch { /* 尚未就绪 */ }
78	    await new Promise(r => setTimeout(r, 100));
79	  }
80	  throw new Error("服务未在限定时间内就绪：" + base);
81	}
82	
83	async function stopApp(ctx) {
84	  ctx.proc.kill(); // SIGTERM：app.py 收到后走正常关闭
85	  const timer = setTimeout(() => {
86	    try { ctx.proc.kill("SIGKILL"); } catch { /* 已退出 */ }
87	  }, 2000);
88	  await new Promise(r => ctx.proc.on("exit", r));
89	  clearTimeout(timer);
90	}
91	
92	async function importCsv(base, csv) {
93	  const res = await fetch(base + "/api/clients/import", {method: "POST", body: csv});
94	  const data = await res.json();
95	  if (res.status !== 200) throw new Error("seed 失败：" + JSON.stringify(data));
96	  return data;
97	}
98	
99	// 直接打后端准备稳定的测试数据
100	async function seed(base, rows) {
101	  const lines = rows.map(r => [r.name, r.source ?? "", r.region ?? "", r.industry ?? "", r.date ?? ""]
102	    .map(v => `"${String(v).replace(/"/g, '""')}"`).join(","));
103	  const csv = "name,source,region,industry,important_date\n" + lines.join("\n") + "\n";
104	  const data = await importCsv(base, csv);
105	  return data.imported.map(x => x.id);
106	}
107	
108	async function listClients(base) {
109	  const res = await fetch(base + "/api/clients");
110	  return res.json();
111	}
112	
113	// ---------------------------------------------------------------------------
114	// 页面驱动：请求拦截让 GET /api/clients 在「保存后的刷新」中按模式失败
115	// ---------------------------------------------------------------------------
116	async function openSession(browser, base) {
117	  const page = await browser.newPage();
118	  const modes = {
119	    // ok 正常转发；close 连接断开；500 非成功状态；bad-json 无法解析；
120	    // no-clients 可解析但缺少客户数组
121	    list: "ok",
122	    // batch 响应改写：null = 走真实后端；否则用给定 {status, body}
123	    batchOverride: null,
124	  };
125	  const counts = {batchPosts: 0, listGets: 0};
126	
127	  await page.setRequestInterception(true);
128	  page.on("request", request => {
129	    const url = request.url();
130	    if (request.method() === "GET" && url.endsWith("/api/clients")) {
131	      counts.listGets += 1;
132	      if (modes.list === "close") { request.abort("failed"); return; }
133	      if (modes.list === "500") {
134	        request.respond({status: 500, contentType: "application/json; charset=utf-8",
135	          body: JSON.stringify({error: "模拟的服务错误"})});
136	        return;
137	      }
138	      if (modes.list === "bad-json") {
139	        request.respond({status: 200, contentType: "application/json; charset=utf-8",
140	          body: "<<<not valid json>>>"});
141	        return;
142	      }
143	      if (modes.list === "no-clients") {
144	        request.respond({status: 200, contentType: "application/json; charset=utf-8",
145	          body: JSON.stringify({unexpected: true})});
146	        return;
147	      }
148	      request.continue();
149	      return;
150	    }
151	    if (request.method() === "POST" && url.endsWith("/api/clients/batch-update")) {
152	      counts.batchPosts += 1;
153	      if (modes.batchOverride) {
154	        const {status, body} = modes.batchOverride;
155	        request.respond({status, contentType: "application/json; charset=utf-8", body});
156	        return;
157	      }
158	    }
159	    request.continue();
160	  });
161	
162	  await page.setCacheEnabled(false);
163	  await page.goto(base + "/", {waitUntil: "networkidle0"});
164	  return {page, modes, counts};
165	}
166	
167	// 读取批量保存区域的全部可见状态
168	async function snapshot(page) {
169	  return page.evaluate(() => {
170	    const text = sel => document.querySelector(sel)?.textContent.trim() ?? null;
171	    const rows = [...document.querySelectorAll("#clients-body tr")].map(tr => ({
172	      id: tr.dataset.id,
173	      checked: tr.querySelector(".row-check").checked,
174	      selected: tr.classList.contains("selected"),
175	      // td: 0 勾选框, 1 编号, 2 名称, 3 来源, 4 地区, 5 行业, 6 重要日期
176	      cells: [...tr.querySelectorAll("td")].slice(2).map(td => td.textContent.trim()),
177	    }));
178	    return {
179	      selCount: text("#sel-count"),
180	      // renderSelection 重建的提示 span 没有保留静态 id，按可见文案识别更贴近用户所见
181	      selNoneHint: document.querySelector("#sel-list")?.textContent.includes("尚未勾选任何客户") ?? false,
182	      selChips: [...document.querySelectorAll(".sel-chip")]
183	        .map(c => c.textContent.replace(/\s*×$/, "").trim()),
184	      submitText: text("#batch-submit"),
185	      submitDisabled: document.getElementById("batch-submit").disabled,
186	      checkAllChecked: document.getElementById("check-all").checked,
187	      checkAllIndeterminate: document.getElementById("check-all").indeterminate,
188	      tableDisplay: getComputedStyle(document.getElementById("clients-table")).display,
189	      emptyOn: document.getElementById("clients-empty").classList.contains("on"),
190	      loadErrorOn: document.getElementById("clients-load-error").classList.contains("on"),
191	      loadErrorText: text("#clients-load-error"),
192	      rows,
193	      fields: [...document.querySelectorAll("#batch-fields .bf")].map(card => ({
194	        key: card.dataset.field,
195	        op: card.querySelector('input[type=radio]:checked')?.value,
196	        value: card.querySelector(".bf-value").value,
197	        disabled: card.querySelector(".bf-value").disabled,
198	      })),
199	      banners: [...document.querySelectorAll("#batch-report .banner")].map(b => ({
200	        cls: b.className,
201	        text: b.innerText.replace(/[ \t\r\n]+/g, " ").trim(),
202	      })),
203	      reportText: document.getElementById("batch-report").innerText.replace(/[ \t\r\n]+/g, " ").trim(),
204	    };
205	  });
206	}
207	
208	async function selectRows(page, ids) {
209	  await page.evaluate(ids => {
210	    for (const id of ids) {
211	      document.querySelector(`#clients-body tr[data-id="${id}"] .row-check`).click();
212	    }
213	  }, ids);
214	}
215	
216	async function chooseSet(page, key, value) {
217	  await page.evaluate(({key, value}) => {
218	    const card = document.querySelector(`#batch-fields .bf[data-field="${key}"]`);
219	    card.querySelector('input[value=set]').click();
220	    const input = card.querySelector(".bf-value");
221	    input.value = value;
222	    input.dispatchEvent(new Event("input", {bubbles: true}));
223	  }, {key, value});
224	}
225	
226	async function chooseClear(page, key) {
227	  await page.evaluate(key => {
228	    document.querySelector(`#batch-fields .bf[data-field="${key}"] input[value=clear]`).click();
229	  }, key);
230	}
231	
232	async function saveAndSettle(session) {
233	  const {page, counts} = session;
234	  const before = counts.batchPosts;
235	  await page.click("#batch-submit");
236	  await page.waitForSelector("#batch-report .banner", {timeout: 3000});
237	  await page.waitForFunction(
238	    () => document.getElementById("batch-submit").textContent === "保存修改",
239	    {timeout: 5000});
240	  await new Promise(r => setTimeout(r, 50)); // 让横幅/列表提示渲染稳定
241	  return before;
242	}
243	
244	function successBanner(snap, n) {
245	  return snap.banners.some(b => b.cls.includes("ok") &&
246	    new RegExp(`已成功处理\\s*${n}\\s*名客户`).test(b.text));
247	}
248	
249	function listWarnBanner(snap) {
250	  return snap.banners.some(b => b.cls.includes("warn") &&
251	    b.text.includes("读取客户列表失败") &&
252	    b.text.includes("列表暂未更新") &&
253	    b.text.includes("可能仍是保存前") &&
254	    /稍后.*(刷新|重新打开)|重新打开.*刷新/.test(b.text) &&
255	    b.text.includes("无需再次保存"));
256	}
257	
258	function cleanedUp(snap) {
259	  return snap.selCount === "0" &&
260	    snap.selNoneHint && snap.selChips.length === 0 &&
261	    !snap.checkAllChecked && !snap.checkAllIndeterminate &&
262	    snap.rows.every(r => !r.checked && !r.selected) &&
263	    snap.fields.every(f => f.op === "keep" && f.value === "" && f.disabled) &&
264	    snap.submitText === "保存修改" && snap.submitDisabled;
265	}
266	
267	// ---------------------------------------------------------------------------
268	// 测试流程
269	// ---------------------------------------------------------------------------
270	async function run() {
271	  const {proc, port: portPromise} = startApp("main");
272	  let base;
273	  try {
274	    base = `http://127.0.0.1:${await portPromise}`;
275	    await waitReady(base);
276	
277	    const [a, b, c] = await seed(base, [
278	      {name: "页测甲", source: "老客户推荐", region: "华东", industry: "制造业", date: "2020-01-15"},
279	      {name: "页测乙", source: "展会", region: "华南", industry: "零售业", date: "2021-06-30"},
280	      {name: "页测丙", source: "广告", region: "华北", industry: "互联网", date: "2022-12-01"},
281	    ]);
282	
283	    const browser = await puppeteer.launch({
284	      executablePath: process.env.CHROME || "/usr/bin/google-chrome",
285	      headless: true,
286	      args: ["--no-sandbox", "--disable-dev-shm-usage"],
287	    });
288	
289	    try {
290	      // ===================================================================
291	      // 场景 A：保存成功，但随后列表读取「连接失败」
292	      // ===================================================================
293	      {
294	        const session = await openSession(browser, base);
295	        const {page, modes} = session;
296	        const init = await snapshot(page);
297	        check("A 初始：表格显示三名客户", init.rows.length === 3, init.rows);
298	        check("A 初始：无读取失败提示", !init.loadErrorOn, init.loadErrorText);
299	        check("A 初始：已选 0、保存按钮禁用",
300	          init.selCount === "0" && init.submitDisabled,
301	          {sel: init.selCount, disabled: init.submitDisabled});
302	        check("A 初始：四字段均保持原值、输入清空且不可填写",
303	          init.fields.every(f => f.op === "keep" && f.value === "" && f.disabled), init.fields);
304	
305	        await selectRows(page, [a, b]);
306	        await chooseSet(page, "source", "  页面新来源  ");
307	        await chooseClear(page, "industry");
308	        const edited = await snapshot(page);
309	        check("A 填写后：已选 2、按钮可提交、来源可填写、行业选择清空",
310	          edited.selCount === "2" && !edited.submitDisabled &&
311	          edited.fields.find(f => f.key === "source").op === "set" &&
312	          !edited.fields.find(f => f.key === "source").disabled &&
313	          edited.fields.find(f => f.key === "source").value === "  页面新来源  " &&
314	          edited.fields.find(f => f.key === "industry").op === "clear",
315	          edited.fields);
316	
317	        modes.list = "close";
318	        const beforePosts = session.counts.batchPosts;
319	        await saveAndSettle(session);
320	        modes.list = "ok";
321	        const snap = await snapshot(page);
322	
323	        check("A 连接失败：仍明确显示「已成功处理 2 名客户」",
324	          successBanner(snap, 2), snap.banners);
325	        check("A 成功措辞不被改说成全部拒绝/请求失败/尚未保存",
326	          !/全部拒绝|请求失败|尚未保存|没有保存|未保存/.test(snap.reportText),
327	          snap.reportText);
328	        check("A 连接失败：警告同时说明列表暂未更新、可能仍是保存前内容、稍后刷新、无需再次保存",
329	          listWarnBanner(snap), snap.banners);
330	        check("A 连接失败：页内列表读取失败提示也出现", snap.loadErrorOn, snap.loadErrorText);
331	        check("A 连接失败：旧表三行编号/名称/字段全部保留",
332	          snap.rows.length === 3 &&
333	          JSON.stringify(snap.rows.map(r => r.cells[0])) ===
334	            JSON.stringify(["页测甲", "页测乙", "页测丙"]),
335	          snap.rows);
336	        check("A 连接失败：旧表仍是保存前来源（读取失败未清空也未更新表格）",
337	          snap.rows.find(r => r.id === String(a)).cells[1] === "老客户推荐" &&
338	          snap.rows.find(r => r.id === String(b)).cells[1] === "展会",
339	          snap.rows);
340	        check("A 连接失败：不显示「还没有客户记录」，表格仍可见",
341	          !snap.emptyOn && snap.tableDisplay === "table",
342	          {empty: snap.emptyOn, display: snap.tableDisplay});
343	        check("A 连接失败：勾选清零、已选归零、四字段恢复保持原值且输入清空禁用、按钮恢复禁用",
344	          cleanedUp(snap), {sel: snap.selCount, fields: snap.fields, btn: snap.submitText,
345	            disabled: snap.submitDisabled});
346	        check("A 连接失败：保存请求只发出一次，未因读取失败重发修改",
347	          session.counts.batchPosts === beforePosts + 1,
348	          `batch posts=${session.counts.batchPosts}`);
349	
350	        // 后端数据确已落库——成功结论只取决于保存回复
351	        const real = await listClients(base);
352	        check("A 连接失败：后端来源已保存、行业已清空",
353	          real.clients.find(x => x.id === a).source === "页面新来源" &&
354	          real.clients.find(x => x.id === a).industry === null &&
355	          real.clients.find(x => x.id === b).source === "页面新来源",
356	          real.clients);
357	        check("A 连接失败：未勾选客户完全不变",
358	          real.clients.find(x => x.id === c).source === "广告" &&
359	          real.clients.find(x => x.id === c).industry === "互联网",
360	          real.clients.find(x => x.id === c));
361	
362	        // 随后刷新页面、读取成功：撤下失败提示并显示真实资料
363	        modes.list = "ok";
364	        await page.reload({waitUntil: "networkidle0"});
365	        const refreshed = await snapshot(page);
366	        check("A 刷新后：读取失败提示撤下", !refreshed.loadErrorOn, refreshed.loadErrorText);
367	        check("A 刷新后：显示真实保存结果（来源已更新、行业为空）",
368	          refreshed.rows.find(r => r.id === String(a)).cells[1] === "页面新来源" &&
369	          refreshed.rows.find(r => r.id === String(a)).cells[3] === "—" &&
370	          refreshed.rows.find(r => r.id === String(c)).cells[1] === "广告",
371	          refreshed.rows);
372	        check("A 刷新后：无勾选残留、四字段保持原值、按钮禁用", cleanedUp(refreshed),
373	          {sel: refreshed.selCount, fields: refreshed.fields});
374	        await page.close();
375	      }
376	
377	      // ===================================================================
378	      // 场景 B：保存成功，列表返回 HTTP 500（非成功状态）
379	      // ===================================================================
380	      {
381	        const session = await openSession(browser, base);
382	        const {page, modes} = session;
383	        await selectRows(page, [a, b]);
384	        await chooseSet(page, "region", "  新区号  ");
385	        modes.list = "500";
386	        const beforePosts = session.counts.batchPosts;
387	        await saveAndSettle(session);
388	        modes.list = "ok";
389	        const snap = await snapshot(page);
390	
391	        check("B 500：仍显示已成功处理 2 名", successBanner(snap, 2), snap.banners);
392	        check("B 500：警告说明列表暂未更新、稍后刷新、无需再次保存",
393	          listWarnBanner(snap), snap.banners);
394	        check("B 500：页内失败提示出现", snap.loadErrorOn, snap.loadErrorText);
395	        check("B 500：旧表三行保留、不显示空列表提示",
396	          snap.rows.length === 3 && !snap.emptyOn, snap.rows);
397	        check("B 500：勾选与编辑全部清理、按钮恢复且禁用", cleanedUp(snap),
398	          {sel: snap.selCount, fields: snap.fields});
399	        check("B 500：保存请求未重发",
400	          session.counts.batchPosts === beforePosts + 1, session.counts.batchPosts);
401	        check("B 500：后端地区确已保存",
402	          (await listClients(base)).clients.find(x => x.id === a).region === "新区号",
403	          "后端 region");
404	        await page.close();
405	      }
406	
407	      // ===================================================================
