561	def parse_csv(text):
562	    """解析 RFC 4180 风格 CSV，返回 (header, data_rows)。
563	
564	    支持引号包裹的字段、引号内逗号与换行、双引号转义；
565	    引号外支持 LF / CRLF / CR 换行。结构损坏时抛 FileError：
566	    - 未加引号的字段中出现双引号（双引号只能在字段开头用于包住整个字段）；
567	    - 结束引号后出现逗号、换行或文件结束以外的字符（含空格）；
568	    - 文件结束时仍有字段处于引号内（引号未闭合）。
569	    错误信息区分上述三种情况，并指出发生在表头还是第 N 条数据记录
570	    （数据记录编号不包含表头，引号字段内的换行不增加编号）。
571	    """
572	    rows = []
573	    record = []
574	    field = []
575	    quoted = False        # 当前字段处于引号内
576	    started = False       # 当前字段已经开始（已有内容或已进入引号）
577	    closed = False       # 引号字段刚结束，等待逗号 / 换行 / 文件结束
578	    record_number = 0     # 0 = 表头，1 起为数据记录
579	    i = 0
580	    n = len(text)
581	
582	    def location():
583	        return "表头" if record_number == 0 else "第 %d 条数据记录" % record_number
584	
585	    def structure_error(kind):
586	        raise FileError("CSV 结构损坏（%s）：%s" % (location(), kind))
587	
588	    def finish_record():
589	        nonlocal record, field, started, closed
590	        record.append("".join(field))
591	        rows.append(record)
592	        record = []
593	        field = []
594	        started = False
595	        closed = False
596	
597	    while i < n:
598	        c = text[i]
599	        if quoted:
600	            if c == '"':
601	                if i + 1 < n and text[i + 1] == '"':
602	                    field.append('"')
603	                    i += 2
604	                    continue
605	                quoted = False
606	                closed = True
607	                i += 1
608	                continue
609	            if c == "\r":
610	                # 统一字段内换行符为 LF
611	                if i + 1 < n and text[i + 1] == "\n":
612	                    i += 1
613	                field.append("\n")
614	                i += 1
615	                continue
616	            field.append(c)
617	            i += 1
618	            continue
619	        if closed:
620	            # 引号已结束，只允许逗号、记录换行或文件结束
621	            if c == ",":
622	                record.append("".join(field))
623	                field = []
624	                started = False
625	                closed = False
626	            elif c in "\r\n":
627	                if c == "\r" and i + 1 < n and text[i + 1] == "\n":
628	                    i += 1
629	                finish_record()
630	                record_number += 1
631	            else:
632	                structure_error("结束引号后有多余字符，结束引号后只能紧接逗号、记录换行或文件结束")
633	            i += 1
634	            continue
635	        if c == '"' and not started:
636	            quoted = True
637	            started = True
638	        elif c == '"':
639	            structure_error("未加引号的字段中出现双引号，双引号只能在字段开头用于包住整个字段")
640	        elif c == ",":
641	            record.append("".join(field))
642	            field = []
643	            started = False
644	        elif c in "\r\n":
645	            if c == "\r" and i + 1 < n and text[i + 1] == "\n":
646	                i += 1
647	            if not started and not record and not field:
648	                # 空白行：不作为数据记录（显式的 "" 空字段 started=True，仍会保留）
649	                i += 1
650	                continue
651	            finish_record()
652	            record_number += 1
653	        else:
654	            field.append(c)
655	            started = True
656	        i += 1
657	    if quoted:
658	        structure_error("引号未闭合，文件结束时仍有字段处于引号内")
659	    if started or field or record or closed:
660	        record.append("".join(field))
661	        rows.append(record)
662	    if not rows:
663	        raise FileError("CSV 内容为空：缺少表头")
664	    return rows[0], rows[1:]
