await new Promise(rs => setTimeout(rs, 200));
const after = await page.evaluate(() => ({url: location.href}));
console.log("page.click on disabled button did not throw; url still:", after.url);
await browser.close();
EOF
node click_probe.mjs; rm -f click_probe.mjs

